  const value = process.env[key];
  if (!value) {
    if (process.env.NODE_ENV === "test" || process.env.JEST_WORKER_ID) {
      return `test-${key.toLowerCase()}`;
    }
    throw new Error(`Missing required environment variable: ${key}`);
  }
  return value;
};

