  var __sanityClient: SanityClient | undefined;
  // eslint-disable-next-line no-var
  var __sanityPreviewClient: SanityClient | undefined;
}

const createCachedClient = (
  config: ClientConfig,
  cacheKey: "__sanityClient" | "__sanityPreviewClient"
): SanityClient => {
